import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.1lR7qgqY.js";const u=JSON.parse('{"title":"術語對照","description":"","frontmatter":{},"headers":[],"relativePath":"ref/glossary.md","filePath":"ref/glossary.md","lastUpdated":null}'),o={name:"ref/glossary.md"};function n(i,t,l,s,c,h){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="術語對照" tabindex="-1">術語對照 <a class="header-anchor" href="#術語對照" aria-label="Permalink to &quot;術語對照&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本頁說明</p><ul><li>依台灣常用說法整理, 對照尚未以國家教育研究院雙語詞彙核對 (信心: 中).</li><li>處理方式分三種: 有通用中文譯名者用中文, 首次出現附原文; 業界慣用英文者直接用英文; 沒有通用譯名者保留英文, 不自創譯名.</li><li>新增或修改術語請開 PR, 並在說明中附上所依據的台灣用法來源.</li></ul></div><h2 id="採用中文" tabindex="-1">採用中文 <a class="header-anchor" href="#採用中文" aria-label="Permalink to &quot;採用中文&quot;">​</a></h2><table tabindex="0"><thead><tr><th>中文</th><th>原文</th><th>說明</th></tr></thead><tbody><tr><td>推論</td><td>inference</td><td>使用已訓練好的模型產生回答</td></tr><tr><td>微調</td><td>fine-tuning</td><td>以少量資料調整既有模型</td></tr><tr><td>預訓練</td><td>pretraining</td><td>從零開始訓練模型</td></tr><tr><td>權重</td><td>weights</td><td>模型學到的參數</td></tr><tr><td>量化</td><td>quantization</td><td>降低權重精度以節省記憶體</td></tr><tr><td>檢索增強生成</td><td>RAG (Retrieval-Augmented Generation)</td><td>先檢索文件, 再讓模型依文件回答</td></tr><tr><td>嵌入</td><td>embedding</td><td>把文字轉成向量</td></tr><tr><td>向量庫</td><td>vector database</td><td>儲存與查詢向量的資料庫</td></tr><tr><td>重排序</td><td>reranking</td><td>對檢索結果重新排序</td></tr><tr><td>閘道</td><td>gateway</td><td>統一入口, 負責路由, 金鑰與配額</td></tr><tr><td>沙箱</td><td>sandbox</td><td>隔離執行環境</td></tr><tr><td>護欄</td><td>guardrail</td><td>檢查模型輸入與輸出的機制</td></tr><tr><td>提示注入</td><td>prompt injection</td><td>在輸入中夾帶指令, 誘使模型偏離原本任務</td></tr><tr><td>工具呼叫</td><td>function calling / tool calling</td><td>模型輸出結構化指令, 由程式執行</td></tr><tr><td>供應鏈</td><td>supply chain</td><td>軟體所依賴的上游元件與發布流程</td></tr><tr><td>摘要值</td><td>digest</td><td>容器映像的雜湊值, 用來鎖定確切內容</td></tr><tr><td>上下文</td><td>context</td><td>模型一次能處理的輸入範圍</td></tr><tr><td>稽核</td><td>audit</td><td>-</td></tr><tr><td>利害關係人</td><td>stakeholder</td><td>-</td></tr></tbody></table><h2 id="保留英文" tabindex="-1">保留英文 <a class="header-anchor" href="#保留英文" aria-label="Permalink to &quot;保留英文&quot;">​</a></h2><table tabindex="0"><thead><tr><th>術語</th><th>說明</th></tr></thead><tbody><tr><td>token</td><td>文字被切成的最小處理單位. 不譯為「詞元」, 因該詞為中國大陸用語 (來源: 世界日報報導, 待核對)</td></tr><tr><td>KV cache</td><td>推論時暫存注意力運算結果的記憶體</td></tr><tr><td>LoRA, QLoRA</td><td>低秩適配微調方法</td></tr><tr><td>MCP</td><td>Model Context Protocol, 模型與外部工具之間的協定</td></tr><tr><td>PoC, scope, onboarding, roadmap, runbook</td><td>業界慣用英文</td></tr><tr><td>GGUF, safetensors</td><td>模型檔格式</td></tr><tr><td>開源 / 原始碼公開</td><td>見<a href="/docs-handbook-poc/ref/licenses">授權速查</a>: 前者指符合 OSI 定義, 後者指原始碼可看但使用有限制</td></tr></tbody></table><h2 id="禁用的中國大陸用語" tabindex="-1">禁用的中國大陸用語 <a class="header-anchor" href="#禁用的中國大陸用語" aria-label="Permalink to &quot;禁用的中國大陸用語&quot;">​</a></h2><p>軟件, 信息, 數據(指一般資料), 網絡, 質量, 項目, 用戶, 默認, 文件(指 file), 接口, 代碼, 算法, 智能, 審計, 利益相關者, 最佳實踐. 一律改用台灣慣用語.</p>',8)])])}const p=d(o,[["render",n]]);export{u as __pageData,p as default};
